import pandas as pd
from pathlib import Path

# ---------------------------------------------------------------------------
# Keyword‑based typology inference for UNKNOWN buildings
# ---------------------------------------------------------------------------
# This script reads the building‑parameter observations CSV generated by the
# frequency pipeline, extracts all rows where the original typology is UNKNOWN,
# concatenates the evidence text for each building, and attempts to guess a
# typology using a simple keyword dictionary.
# ---------------------------------------------------------------------------

CSV_PATH = Path("data/analysis/building_parameter_observations.csv")
OUT_PATH = Path("data/analysis/unknown_typology_keyword_scan.csv")

# 1️⃣ Load observations
df = pd.read_csv(CSV_PATH)

# 2️⃣ Keep only UNKNOWN buildings
unknown = df[df["typology"] == "UNKNOWN"]

# 3️⃣ Group evidence per building (concatenate all evidence strings)
#    We also keep the source_document column for reference.
grouped = (
    unknown.groupby("building_id")
    .agg(
        evidence_text=pd.NamedAgg(column="evidence_text", aggfunc=lambda s: " ".join(filter(None, s))),
        source_documents=pd.NamedAgg(column="source_document", aggfunc=lambda s: ", ".join(set(filter(None, s)))),
    )
    .reset_index()
)

# ---------------------------------------------------------------------------
# Keyword dictionary – map keyword (lower‑case) -> typology label
# You can extend this dictionary with additional terms as needed.
# ---------------------------------------------------------------------------
KEYWORD_MAP = {
    "reinforced concrete": "RC",
    "rc ": "RC",
    "concrete": "RC",
    "steel": "RC",
    "stone": "RRSM",
    "masonry": "RRSM",
    "mud mortar": "RRSM",
    "brick": "BCBM",
    "brick chimney": "BCBM",
    "timber": "TIMBER",
    "wood": "TIMBER",
}

def guess_typology(evidence: str) -> str:
    """Return a typology based on the first matching keyword.

    The function lower‑cases the evidence string and checks each keyword in the
    order defined in ``KEYWORD_MAP``. If none match, ``UNKNOWN`` is returned.
    """
    lowered = evidence.lower()
    for kw, typ in KEYWORD_MAP.items():
        if kw in lowered:
            return typ
    return "UNKNOWN"

# 4️⃣ Apply the keyword scan
grouped["keyword_guess"] = grouped["evidence_text"].apply(guess_typology)

# 5️⃣ Save results for review
OUT_PATH.parent.mkdir(parents=True, exist_ok=True)
grouped.to_csv(OUT_PATH, index=False)
print(f"OK Keyword‑based typology suggestions written to {OUT_PATH}")
print("Sample of results:")
print(grouped.head())
